// Map the Galapagos tool name to its Darwin tool sub-workflow, parse the
// arguments, and record the start time for the log row (DWN-81).
const TOOLS = {
  search: 'SeM49wLBqaM1KknA',
  ls: 'dLWwo63SMOZqfYfJ',
  get_resource_context: 'Zfh4IcfyPk9fICFe',
  get_transcript: 'jUXyju77iBG3FGUz',
  get_session: 'MDkAHGs3zAt0KGNm',
  get_project: 'B81Gkws52MZNrzJZ',
  get_forum_thread: 'Ft4amYKPNROF6WLy',
  get_gong_call: 'TvvDElh9iRoPoU7B',
  get_scheduled_sessions: 'Ngwj2PVZOYGh7wTU',
};
const t = $input.first().json;
let args = {};
if (t.args && typeof t.args === 'object') args = t.args;
else if (t.args) { try { args = JSON.parse(t.args); } catch (e) { args = { _unparsed: String(t.args) }; } }
const blank = (v) => v === undefined || v === null || v === '' || v === '__UNKNOWN__';
// Note: never name a key 'caller' here. The n8n expression sandbox blocks
// access to a property with that name, so downstream expressions fail.
return [{ json: { ...args, _galapagos: {
  tool: String(t.tool || ''),
  workflow_id: TOOLS[t.tool] || 'unknown-tool',
  args,
  via: blank(t.caller) ? 'galapagos' : String(t.caller),
  user_id: blank(t.user_id) ? null : String(t.user_id),
  user_email: blank(t.user_email) ? null : String(t.user_email),
  user_name: blank(t.user_name) ? null : String(t.user_name),
  execution_id: blank(t.parent_execution_id) ? String($execution.id) : String(t.parent_execution_id),
  started_ms: Date.now(),
} } }];

// One log row per call. Status is 'error' when the tool output is a single
// { error } item: an n8n failure (Run Tool continues on error) or an error
// the tool reported itself. Otherwise 'success'.
const m = $('Prepare').first().json._galapagos;
const result = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length > 0);
const isError = result.length === 1 && result[0].error !== undefined && Object.keys(result[0]).every(k => ['error', 'path'].includes(k));
let msg = null;
if (isError) {
  const e = result[0].error;
  msg = typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
  if (m.workflow_id === 'unknown-tool') msg = 'Unknown tool: ' + m.tool;
}
const text = JSON.stringify(result);
return [{ json: { result, isError, message: msg, log: {
  server: 'galapagos', via: m.via, tool: m.tool,
  user_id: m.user_id, user_email: m.user_email, user_name: m.user_name,
  args: m.args, status: isError ? 'error' : 'success', error: msg ? String(msg).slice(0, 4000) : null,
  duration_ms: Date.now() - m.started_ms,
  result_bytes: isError ? 0 : text.length, result_items: isError ? 0 : result.length,
  n8n_execution_id: m.execution_id,
} } }];

// Return the tool output unchanged (the log insert result must not leak).
const b = $('Build Log').first().json;
if (b.isError) return [{ json: { error: b.message } }];
if (!b.result.length) return [{ json: { message: 'The tool returned no results.' } }];
return b.result.map(r => ({ json: r }));
